<?php
if(!defined('ABSPATH'))exit;
function dgs_edu_url($tab='overview',$year=''){return add_query_arg(array('dg_tab'=>$tab,'dg_year'=>$year?:dgs_edu_request_year()),dgs_page_url('portal'));}
function dgs_edu_form_start($operation,$tab,$year){return '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="dge-form"><input type="hidden" name="action" value="dgs_education"><input type="hidden" name="operation" value="'.esc_attr($operation).'"><input type="hidden" name="return_tab" value="'.esc_attr($tab).'"><input type="hidden" name="year" value="'.esc_attr($year).'">'.wp_nonce_field('dgs_education','dgs_edu_nonce',true,false);}
function dgs_edu_select($name,$label,$items,$selected=0,$required=true){$out='<label>'.esc_html($label).'<select name="'.esc_attr($name).'" '.($required?'required':'').'><option value="">انتخاب کنید</option>';foreach($items as $value=>$text)$out.='<option value="'.esc_attr($value).'" '.selected((string)$selected,(string)$value,false).'>'.esc_html($text).'</option>';return $out.'</select></label>';}
function dgs_edu_class_options($classes){$out=array();foreach($classes as $c)$out[$c->id]=dgs_edu_grade_label($c->grade).' '.$c->title.' — '.(dgs_edu_fields()[$c->field]??'');return $out;}
function dgs_edu_user_options($role){$users=get_users(array('role'=>$role,'number'=>1000,'orderby'=>'display_name','order'=>'ASC','fields'=>array('ID','display_name')));$out=array();foreach($users as $u){if(user_can($u->ID,'manage_options'))continue;$out[$u->ID]=$u->display_name.' (#'.$u->ID.')';}return $out;}
function dgs_edu_table_start($headers){$out='<div class="dge-table-wrap" tabindex="0" aria-label="جدول؛ در صفحه کوچک قابل پیمایش است"><table class="dge-table"><thead><tr>';foreach($headers as $h)$out.='<th scope="col">'.esc_html($h).'</th>';return $out.'</tr></thead><tbody>';}
function dgs_edu_flash(){if(!isset($_GET['dg_notice'])||!is_string($_GET['dg_notice'])||!preg_match('/^[a-zA-Z0-9]{24}$/D',$_GET['dg_notice']))return '';$key='dgs_edu_flash_'.get_current_user_id().'_'.$_GET['dg_notice'];$data=get_transient($key);if(!is_array($data))return '';delete_transient($key);return '<div class="dg-alert '.(!empty($data['error'])?'dge-error':'dg-success').'" role="status">'.esc_html($data['text']).'</div>';}
function dgs_edu_portal(){
    if(!is_user_logged_in())return '';
    $u=wp_get_current_user();$year=dgs_edu_request_year();$manager=current_user_can('dgs_manage_education');
    $role=$manager?'مدیر و معاون':(dgs_edu_role($u,'dgs_teacher')?'معلم':(dgs_edu_role($u,'dgs_counselor')?'مشاور':(dgs_edu_role($u,'dgs_student')?'دانش‌آموز':'حساب کاربری')));
    $out='<div class="dge-portal"><header class="dge-heading"><div><span class="dg-kicker">سامانه مدرسه دانشگران · '.esc_html($role).'</span><h2>سلام '.esc_html($u->display_name).'، خوش آمدید</h2></div><a class="dg-btn dg-btn-outline" href="'.esc_url(wp_logout_url(home_url('/'))).'">خروج</a></header>';
    $out.='<form class="dge-year-filter" method="get" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="'.esc_attr(dgs_portal_tab()).'"><label>سال تحصیلی<input name="dg_year" value="'.esc_attr($year).'" dir="ltr" pattern="14[0-9]{2}-14[0-9]{2}" required></label><button class="dg-btn dg-btn-outline">نمایش</button></form>';
    $tab=dgs_portal_tab();$tabs=dgs_portal_links();
    if($tabs){$out.='<nav class="dge-tabs" aria-label="منوی پنل">';foreach($tabs as $key=>$item)$out.='<a '.($tab===$key?'aria-current="page"':'').' href="'.esc_url(dgs_edu_url($key,$year)).'">'.esc_html($item[0]).'</a>';$out.='</nav>';}
    $out.=dgs_edu_flash();
    if($manager){if($tab==='overview')$out.=dgs_school_manager_dashboard($year);else{$callback='dgs_edu_view_'.$tab;$out.=$callback($year);}}
    elseif($tabs){
      if($tab==='timetable')$out.=dgs_school_timetable_page($year);
      elseif($tab==='homework')$out.=dgs_hw_portal($year);
      elseif($tab==='quizzes')$out.=dgs_quiz_portal($year);
      elseif($tab==='grades')$out.=dgs_grade_panel($year);
      elseif($tab==='password')$out.=dgs_edu_password_form();
      elseif($tab==='attendance')$out.=dgs_att_student($year);
      elseif($tab==='finance')$out.=dgs_fin_student($year);
      elseif(dgs_edu_role($u,'dgs_teacher'))$out.=dgs_edu_teacher_view($u->ID,$year);
      elseif(dgs_edu_role($u,'dgs_counselor'))$out.=dgs_edu_counselor_view($u->ID,$year);
      else $out.=dgs_school_student_dashboard($year);
    }else $out.='<p>هنوز نقش مدرسه به حساب شما تخصیص داده نشده است.</p>';
    return $out.'</div>';
}
function dgs_edu_view_overview($year){
    global $wpdb;$t=dgs_edu_tables();$classes=dgs_edu_classes($year);$students=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['enrollments']} e JOIN {$t['classes']} c ON c.id=e.class_id WHERE e.school_year=%s AND c.active=1",$year));$teaching=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['teaching']} a JOIN {$t['classes']} c ON c.id=a.class_id WHERE c.school_year=%s AND c.active=1",$year));$counsel=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$t['counseling']} a JOIN {$t['enrollments']} e ON e.student_id=a.student_id AND e.school_year=a.school_year JOIN {$t['classes']} c ON c.id=e.class_id WHERE a.school_year=%s AND c.active=1",$year));
    $out='<div class="dge-stats">';foreach(array('کلاس فعال'=>count($classes),'دانش‌آموز دارای کلاس'=>$students,'تخصیص دبیر و درس'=>$teaching,'دانش‌آموز دارای مشاور'=>$counsel) as $label=>$value)$out.='<article><span>'.esc_html($label).'</span><strong>'.esc_html(dgs_fa_digits($value)).'</strong></article>';$out.='</div><div class="dge-two"><section class="dge-box"><h3>سال تحصیلی فعال مدرسه</h3>'.dgs_edu_form_start('year','overview',$year).'<label>سال تحصیلی<input name="year" value="'.esc_attr($year).'" dir="ltr" pattern="14[0-9]{2}-14[0-9]{2}" required></label><button class="dg-btn">ذخیره سال فعال</button></form></section><section class="dge-box"><h3>ترتیب آماده‌سازی</h3><ol><li>کلاس‌ها و درس‌ها را تعریف کنید.</li><li>حساب دانش‌آموز، معلم و مشاور را بسازید.</li><li>دانش‌آموزان را به کلاس تخصیص دهید.</li><li>دبیر هر درس و مشاور دانش‌آموز را تعیین کنید.</li></ol></section></div>';
    if(current_user_can('edit_dgs_requests'))$out.='<a class="dg-btn dg-btn-outline" href="'.esc_url(admin_url('edit.php?post_type=dgs_request')).'">درخواست‌های پیش‌ثبت‌نام</a>';
    return $out;
}
function dgs_edu_view_classes($year){
    $out='<section class="dge-box"><h3>افزودن کلاس مدرسه</h3>'.dgs_edu_form_start('class_create','classes',$year).'<div class="dge-grid"><label>نام کلاس<input name="title" maxlength="100" placeholder="مثلاً ۱ یا الف" required></label>'.dgs_edu_select('grade','پایه',array(10=>'دهم',11=>'یازدهم',12=>'دوازدهم')).dgs_edu_select('field','رشته',dgs_edu_fields()).'</div><button class="dg-btn">افزودن کلاس</button></form></section><section class="dge-box"><h3>کلاس‌های سال '.esc_html(dgs_fa_digits($year)).'</h3>';
    $classes=dgs_edu_classes($year,true);if(!$classes)return $out.dgs_empty('هنوز کلاسی برای این سال تعریف نشده است.').'</section>';
    $out.=dgs_edu_table_start(array('کلاس','پایه','رشته','دانش‌آموز','وضعیت','عملیات'));
    foreach($classes as $c){$out.='<tr><td>'.esc_html($c->title).'</td><td>'.esc_html(dgs_edu_grade_label($c->grade)).'</td><td>'.esc_html(dgs_edu_fields()[$c->field]??'').'</td><td>'.esc_html(dgs_fa_digits($c->students_count)).'</td><td>'.($c->active?'فعال':'بایگانی').'</td><td>'.dgs_edu_form_start('class_status','classes',$year).'<input type="hidden" name="class_id" value="'.(int)$c->id.'"><input type="hidden" name="active" value="'.($c->active?'0':'1').'"><button class="dge-small-btn" '.($c->active?'data-dge-confirm="کلاس بایگانی شود؟ اعضا و سوابق حذف نمی‌شوند."':'').'>'.($c->active?'بایگانی':'فعال‌سازی').'</button></form></td></tr>';}
    return $out.'</tbody></table></div></section>';
}
function dgs_edu_view_subjects($year){$out='<section class="dge-box"><h3>تعریف درس</h3>'.dgs_edu_form_start('subject_create','subjects',$year).'<label>نام درس<input name="title" maxlength="100" required placeholder="مثلاً ریاضی ۲"></label><button class="dg-btn">افزودن درس</button></form></section><section class="dge-box"><h3>فهرست درس‌ها</h3>';foreach(dgs_edu_subjects() as $s)$out.='<span class="dge-pill">'.esc_html($s->title).'</span>';return $out.'</section>';}
function dgs_edu_view_users($year){
    $role=isset($_GET['school_role'])&&is_string($_GET['school_role'])?sanitize_key($_GET['school_role']):'dgs_student';$roles=array('dgs_student'=>'دانش‌آموز','dgs_teacher'=>'معلم','dgs_counselor'=>'مشاور');if(!isset($roles[$role]))$role='dgs_student';$page=max(1,min(10000,absint($_GET['users_page']??1)));$search=isset($_GET['student_search'])&&is_string($_GET['student_search'])?sanitize_text_field(wp_unslash($_GET['student_search'])):'';
    $args=array('role'=>$role,'number'=>20,'paged'=>$page,'orderby'=>'display_name','order'=>'ASC','count_total'=>true);if($search!==''){$args['search']='*'.$search.'*';$args['search_columns']=array('user_login','display_name','user_email');}$query=new WP_User_Query($args);
    $out='<details class="dge-box"><summary>افزودن حساب دانش‌آموز، معلم یا مشاور</summary>'.dgs_edu_form_start('user_create','users',$year).'<div class="dge-grid"><label>نام و نام خانوادگی<input name="name" maxlength="100" required autocomplete="off"></label>'.dgs_edu_select('role','نقش',$roles).'<label>کد ملی (نام کاربری و رمز اولیه)<input name="national_id" inputmode="numeric" minlength="10" maxlength="10" dir="ltr" autocomplete="off" required></label><label>شماره تماس همراه (الزامی، فقط مدیریت)<input name="phone" inputmode="tel" dir="ltr" maxlength="18" autocomplete="off" required></label></div><p class="dg-muted">نام کاربری و رمز اولیه کد ملی است. پس از ورود می‌توانید رمز را تغییر دهید. نام کاربری ثابت می‌ماند. نقش حساب از این فرم فقط یکی از نقش‌های مدرسه خواهد بود. ساخت معاون از بخش کاربران وردپرس و فقط توسط مدیرکل انجام می‌شود.</p><button class="dg-btn">ساخت حساب</button></form></details>';
    $out.='<section class="dge-box"><h3>کاربران مدرسه</h3><form method="get" action="'.esc_url(dgs_page_url('portal')).'" class="dge-filter"><input type="hidden" name="dg_tab" value="users"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('school_role','نقش',$roles,$role).'<label>نام، نام کاربری یا ایمیل<input name="student_search" value="'.esc_attr($search).'" maxlength="100"></label><button class="dg-btn dg-btn-outline">جست‌وجو</button></form>';
    $out.=dgs_edu_table_start(array('نام و نام خانوادگی','نام کاربری','نقش','شماره تماس'));
    foreach($query->get_results() as $u){if(user_can($u,'manage_options'))continue;$out.='<tr><td>'.esc_html($u->display_name).'</td><td dir="ltr">'.esc_html($u->user_login).'</td><td>'.esc_html($roles[$role]).'</td><td dir="ltr">'.esc_html(get_user_meta($u->ID,'_dgs_contact_phone',true)).'</td></tr>';}
    $out.='</tbody></table></div><nav class="dge-pagination" aria-label="صفحه‌بندی کاربران">';$total=(int)ceil($query->get_total()/20);if($page>1)$out.='<a href="'.esc_url(add_query_arg(array('users_page'=>$page-1,'school_role'=>$role,'student_search'=>$search),dgs_edu_url('users',$year))).'">قبلی</a>';$out.='<span>'.esc_html(dgs_fa_digits($page)).' / '.esc_html(dgs_fa_digits(max(1,$total))).'</span>';if($page<$total)$out.='<a href="'.esc_url(add_query_arg(array('users_page'=>$page+1,'school_role'=>$role,'student_search'=>$search),dgs_edu_url('users',$year))).'">بعدی</a>';return $out.'</nav></section>';
}
function dgs_edu_view_assignments($year){
    global $wpdb;$t=dgs_edu_tables();$classes=dgs_edu_classes($year);if(!$classes)return dgs_empty('ابتدا در بخش کلاس‌ها یک کلاس فعال تعریف کنید.');$options=dgs_edu_class_options($classes);$class_id=absint($_GET['dg_class']??0);if(!isset($options[$class_id]))$class_id=(int)$classes[0]->id;
    $out='<div class="dge-two"><section class="dge-box"><h3>تخصیص دانش‌آموزان به کلاس</h3>'.dgs_edu_form_start('enroll','assignments',$year).dgs_edu_select('class_id','کلاس مقصد',$options,$class_id).'<fieldset class="dge-checklist"><legend>دانش‌آموزان</legend>';
    $students=dgs_edu_user_options('dgs_student');foreach($students as $id=>$name)$out.='<label><input type="checkbox" name="students[]" value="'.(int)$id.'"> '.esc_html($name).'</label>';if(!$students)$out.='<p>ابتدا حساب دانش‌آموز بسازید.</p>';
    $out.='</fieldset><p class="dg-muted">هر دانش‌آموز در هر سال فقط یک کلاس دارد. برای جابه‌جایی، ابتدا تخصیص کلاس قبلی را بردارید.</p><button class="dg-btn">تخصیص دانش‌آموزان</button></form></section><section class="dge-box"><h3>تخصیص دبیر به کلاس و درس</h3>'.dgs_edu_form_start('teach','assignments',$year).dgs_edu_select('class_id','کلاس',$options,$class_id);$subjects=array();foreach(dgs_edu_subjects() as $s)$subjects[$s->id]=$s->title;
    $out.=dgs_edu_select('subject_id','درس',$subjects).dgs_edu_select('teacher_id','معلم',dgs_edu_user_options('dgs_teacher')).'<label class="dge-consent"><input type="checkbox" name="replace" value="1">در صورت وجود دبیر قبلی، جایگزین شود.</label><button class="dg-btn">ذخیره تخصیص دبیر</button></form></section></div><section class="dge-box"><h3>اعضا و دبیران کلاس</h3><form method="get" action="'.esc_url(dgs_page_url('portal')).'" class="dge-filter"><input type="hidden" name="dg_tab" value="assignments"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('dg_class','کلاس',$options,$class_id).'<button class="dg-btn dg-btn-outline">نمایش کلاس</button></form>';
    $roster=$wpdb->get_results($wpdb->prepare("SELECT e.id,u.display_name FROM {$t['enrollments']} e JOIN {$wpdb->users} u ON u.ID=e.student_id WHERE e.class_id=%d ORDER BY u.display_name,e.id",$class_id));
    $out.=dgs_edu_table_start(array('دانش‌آموز','عملیات'));foreach($roster as $r)$out.='<tr><td>'.esc_html($r->display_name).'</td><td>'.dgs_edu_form_start('unenroll','assignments',$year).'<input type="hidden" name="enrollment_id" value="'.(int)$r->id.'"><button class="dge-small-btn" data-dge-confirm="تخصیص کلاس این دانش‌آموز برداشته شود؟ حساب حذف نمی‌شود.">برداشتن تخصیص</button></form></td></tr>';$out.='</tbody></table></div>';
    $teaching=$wpdb->get_results($wpdb->prepare("SELECT a.id,s.title,u.display_name FROM {$t['teaching']} a JOIN {$t['subjects']} s ON s.id=a.subject_id JOIN {$wpdb->users} u ON u.ID=a.teacher_id WHERE a.class_id=%d ORDER BY s.title",$class_id));
    $out.='<h3>دبیران این کلاس</h3>'.dgs_edu_table_start(array('درس','معلم','عملیات'));foreach($teaching as $r)$out.='<tr><td>'.esc_html($r->title).'</td><td>'.esc_html($r->display_name).'</td><td>'.dgs_edu_form_start('unteach','assignments',$year).'<input type="hidden" name="teaching_id" value="'.(int)$r->id.'"><button class="dge-small-btn" data-dge-confirm="تخصیص این دبیر برداشته شود؟">برداشتن تخصیص</button></form></td></tr>';return $out.'</tbody></table></div></section>';
}
function dgs_edu_view_counseling($year){
    global $wpdb;$t=dgs_edu_tables();$students=$wpdb->get_results($wpdb->prepare("SELECT e.student_id,u.display_name,c.title,c.grade FROM {$t['enrollments']} e JOIN {$wpdb->users} u ON u.ID=e.student_id JOIN {$t['classes']} c ON c.id=e.class_id WHERE e.school_year=%s AND c.active=1 ORDER BY u.display_name",$year));$opts=array();foreach($students as $s)$opts[$s->student_id]=$s->display_name.' — '.dgs_edu_grade_label($s->grade).' '.$s->title;
    $out='<section class="dge-box"><h3>تعیین مشاور دانش‌آموز</h3>'.dgs_edu_form_start('counsel','counseling',$year).'<div class="dge-grid">'.dgs_edu_select('student_id','دانش‌آموز دارای کلاس',$opts).dgs_edu_select('counselor_id','مشاور',dgs_edu_user_options('dgs_counselor')).'</div><label class="dge-consent"><input type="checkbox" name="replace" value="1">در صورت وجود مشاور قبلی، جایگزین شود.</label><button class="dg-btn">تخصیص مشاور</button></form></section><section class="dge-box"><h3>تخصیص‌های مشاوره</h3>';
    $rows=$wpdb->get_results($wpdb->prepare("SELECT a.id,s.display_name AS student_name,u.display_name AS counselor_name FROM {$t['counseling']} a JOIN {$wpdb->users} s ON s.ID=a.student_id JOIN {$wpdb->users} u ON u.ID=a.counselor_id WHERE a.school_year=%s ORDER BY s.display_name",$year));
    $out.=dgs_edu_table_start(array('دانش‌آموز','مشاور','عملیات'));foreach($rows as $r)$out.='<tr><td>'.esc_html($r->student_name).'</td><td>'.esc_html($r->counselor_name).'</td><td>'.dgs_edu_form_start('uncounsel','counseling',$year).'<input type="hidden" name="counseling_id" value="'.(int)$r->id.'"><button class="dge-small-btn" data-dge-confirm="تخصیص مشاور برداشته شود؟">برداشتن تخصیص</button></form></td></tr>';return $out.'</tbody></table></div></section>';
}
function dgs_edu_teacher_view($teacher,$year){
    global $wpdb;$t=dgs_edu_tables();$rows=$wpdb->get_results($wpdb->prepare("SELECT a.class_id,c.title,c.grade,c.field,s.title AS subject FROM {$t['teaching']} a JOIN {$t['classes']} c ON c.id=a.class_id JOIN {$t['subjects']} s ON s.id=a.subject_id WHERE a.teacher_id=%d AND c.school_year=%s AND c.active=1 ORDER BY c.grade,c.title,s.title",$teacher,$year));
    if(!$rows)return dgs_empty('در این سال هنوز کلاس و درسی به شما تخصیص داده نشده است.');$allowed=array();$out='<section class="dge-box"><h3>کلاس‌ها و درس‌های من</h3><div class="dge-class-cards">';foreach($rows as $r){$allowed[$r->class_id]=$r;$out.='<article><span class="dg-kicker">'.esc_html(dgs_edu_grade_label($r->grade)).' — '.esc_html(dgs_edu_fields()[$r->field]??'').'</span><h3>'.esc_html($r->title).'</h3><p>'.esc_html($r->subject).'</p><a class="dg-btn dg-btn-outline" href="'.esc_url(add_query_arg(array('dg_year'=>$year,'dg_class'=>(int)$r->class_id),dgs_page_url('portal'))).'">فهرست دانش‌آموزان</a></article>';}$out.='</div></section>';
    $selected=absint($_GET['dg_class']??0);if(!$selected)$selected=(int)array_key_first($allowed);if(!isset($allowed[$selected]))return $out.'<p class="dge-error">به کلاس انتخاب‌شده دسترسی ندارید.</p>';
    $students=$wpdb->get_results($wpdb->prepare("SELECT u.display_name,c.grade,c.field FROM {$t['enrollments']} e JOIN {$t['classes']} c ON c.id=e.class_id JOIN {$wpdb->users} u ON u.ID=e.student_id WHERE e.class_id=%d AND EXISTS (SELECT 1 FROM {$t['teaching']} a WHERE a.class_id=e.class_id AND a.teacher_id=%d) ORDER BY u.display_name",$selected,$teacher));
    $out.='<section class="dge-box"><h3>دانش‌آموزان کلاس '.esc_html($allowed[$selected]->title).'</h3>'.dgs_edu_table_start(array('نام و نام خانوادگی','پایه','رشته'));foreach($students as $s)$out.='<tr><td>'.esc_html($s->display_name).'</td><td>'.esc_html(dgs_edu_grade_label($s->grade)).'</td><td>'.esc_html(dgs_edu_fields()[$s->field]??'').'</td></tr>';return $out.'</tbody></table></div></section>';
}
function dgs_edu_student_view($student,$year){
    global $wpdb;$t=dgs_edu_tables();$class=$wpdb->get_row($wpdb->prepare("SELECT c.* FROM {$t['enrollments']} e JOIN {$t['classes']} c ON c.id=e.class_id WHERE e.student_id=%d AND e.school_year=%s AND c.active=1",$student,$year));if(!$class)return dgs_empty('در این سال هنوز کلاسی برای شما تعیین نشده است.');
    $out='<section class="dge-box"><h3>کلاس من</h3><div class="dge-stats"><article><span>کلاس</span><strong>'.esc_html($class->title).'</strong></article><article><span>پایه</span><strong>'.esc_html(dgs_edu_grade_label($class->grade)).'</strong></article><article><span>رشته</span><strong>'.esc_html(dgs_edu_fields()[$class->field]??'').'</strong></article></div></section>';
    $rows=$wpdb->get_results($wpdb->prepare("SELECT s.title,u.display_name FROM {$t['teaching']} a JOIN {$t['subjects']} s ON s.id=a.subject_id JOIN {$wpdb->users} u ON u.ID=a.teacher_id WHERE a.class_id=%d ORDER BY s.title",$class->id));$out.='<section class="dge-box"><h3>درس‌ها و معلم‌های کلاس من</h3>'.dgs_edu_table_start(array('درس','معلم'));foreach($rows as $r)$out.='<tr><td>'.esc_html($r->title).'</td><td>'.esc_html($r->display_name).'</td></tr>';$out.='</tbody></table></div></section>';
    $counselor=$wpdb->get_var($wpdb->prepare("SELECT u.display_name FROM {$t['counseling']} a JOIN {$wpdb->users} u ON u.ID=a.counselor_id WHERE a.student_id=%d AND a.school_year=%s",$student,$year));if($counselor)$out.='<section class="dge-box"><h3>مشاور من</h3><p>'.esc_html($counselor).'</p></section>';return $out;
}
function dgs_edu_counselor_view($counselor,$year){
    global $wpdb;$t=dgs_edu_tables();$students=$wpdb->get_results($wpdb->prepare("SELECT u.display_name,c.title,c.grade,c.field FROM {$t['counseling']} a JOIN {$wpdb->users} u ON u.ID=a.student_id JOIN {$t['enrollments']} e ON e.student_id=a.student_id AND e.school_year=a.school_year JOIN {$t['classes']} c ON c.id=e.class_id WHERE a.counselor_id=%d AND a.school_year=%s AND c.active=1 ORDER BY c.grade,c.title,u.display_name",$counselor,$year));
    if(!$students)return dgs_empty('در این سال هنوز دانش‌آموزی به شما تخصیص داده نشده است.');$out='<section class="dge-box"><h3>دانش‌آموزان تحت مسئولیت من</h3>'.dgs_edu_table_start(array('نام و نام خانوادگی','کلاس','پایه','رشته'));foreach($students as $s)$out.='<tr><td>'.esc_html($s->display_name).'</td><td>'.esc_html($s->title).'</td><td>'.esc_html(dgs_edu_grade_label($s->grade)).'</td><td>'.esc_html(dgs_edu_fields()[$s->field]??'').'</td></tr>';return $out.'</tbody></table></div></section>';
}
add_action('wp_enqueue_scripts',function(){
    $p=get_option('dgs_pages',array());if(empty($p['portal'])||!is_page((int)$p['portal']))return;
    wp_register_style('dgs-education',false,array(),'0.2.0');wp_enqueue_style('dgs-education');wp_add_inline_style('dgs-education',file_get_contents(DGS_PATH.'assets/education.css'));
    wp_register_script('dgs-education',false,array(),'0.2.0',true);wp_enqueue_script('dgs-education');wp_add_inline_script('dgs-education',file_get_contents(DGS_PATH.'assets/education.js'));
});

function dgs_edu_password_form(){return '<details class="dge-box"><summary>تغییر رمز عبور</summary><p>نام کاربری ثابت است. پس از تغییر رمز، دوباره وارد شوید.</p><form class="dge-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dgs_change_password">'.wp_nonce_field('dgs_change_password','dgs_password_nonce',true,false).'<label>رمز فعلی<input type="password" name="current_password" autocomplete="current-password" required></label><label>رمز جدید (حداقل ۱۲ نویسه)<input type="password" name="new_password" minlength="12" maxlength="128" autocomplete="new-password" required></label><label>تکرار رمز جدید<input type="password" name="confirm_password" minlength="12" maxlength="128" autocomplete="new-password" required></label><button class="dg-btn">ذخیره رمز جدید</button></form></details>';}
